+class DeleteConfirmationModal {
+  constructor() {
+    this.dialog = document.getElementById('deleteDialog');
+    this.trigger = document.querySelector('.trigger');
+    this.cancelBtn = document.querySelector('.modal-cancel');
+    this.confirmBtn = document.querySelector('.modal-confirm');
+    this.closeBtn = document.querySelector('.modal-close');
+    this.overlay = this.dialog;
+
+    this.initializeListeners();
+  }
+
+  initializeListeners() {
+    this.trigger.addEventListener('click', () => this.open());
+    this.cancelBtn.addEventListener('click', () => this.close());
+    this.closeBtn.addEventListener('click', () => this.close());
+    this.overlay.addEventListener('click', (e) => this.handleOverlayClick(e));
+    this.confirmBtn.addEventListener('click', () => this.handleConfirm());
+
+    document.addEventListener('keydown', (e) => this.handleKeydown(e));
+  }
+
+  open() {
+    this.dialog.classList.add('open');
+    this.dialog.setAttribute('aria-hidden', 'false');
+    document.body.style.overflow = 'hidden';
+    this.confirmBtn.focus();
+  }
+
+  close() {
+    this.dialog.classList.remove('open');
+    this.dialog.setAttribute('aria-hidden', 'true');
+    document.body.style.overflow = 'auto';
+    this.trigger.focus();
+  }
+
+  handleOverlayClick(e) {
+    if (e.target === this.overlay) {
+      this.close();
+    }
+  }
+
+  handleKeydown(e) {
+    if (e.key === 'Escape' && this.dialog.classList.contains('open')) {
+      this.close();
+    }
+  }
+
+  handleConfirm() {
+    console.log('Image deleted successfully');
+    this.close();
+    alert('Image has been deleted from your library.');
+  }
+}
+
+document.addEventListener('DOMContentLoaded', () => {
+  new DeleteConfirmationModal();
